<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Super Admin','College Admin');check_csrf();$roles=db()->query('SELECT id,name FROM roles ORDER BY name')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){try{$name=trim($_POST['name']);$email=trim($_POST['email']);$pwd=$_POST['password'];$role=(int)$_POST['role_id'];if(strlen($pwd)<8)throw new RuntimeException('Password must be at least 8 characters');$s=db()->prepare('INSERT INTO users(role_id,name,email,password_hash,status) VALUES(?,?,?,?,?)');$s->execute([$role,$name,$email,password_hash($pwd,PASSWORD_DEFAULT),'active']);AuditService::log('CREATE','users',(int)db()->lastInsertId(),'User account created');$_SESSION['flash']=['success','User created'];}catch(Throwable $e){$_SESSION['flash']=['danger',$e->getMessage()];}redirect('users.php');}$rows=db()->query('SELECT u.id,u.name,u.email,r.name role_name,u.status,u.created_at FROM users u JOIN roles r ON r.id=u.role_id ORDER BY u.id DESC')->fetchAll();page_top('Identity & Role Management');flash();?><div class="card p-4 mb-3"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="col-md-4"><input name="name" class="form-control" placeholder="Full name" required></div><div class="col-md-4"><input name="email" type="email" class="form-control" placeholder="Email" required></div><div class="col-md-2"><select name="role_id" class="form-select" required><?php foreach($roles as $r):?><option value="<?=e($r['id'])?>"><?=e($r['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input name="password" type="password" class="form-control" placeholder="Password" required></div><div class="col-12"><button class="btn btn-primary">Create Account</button></div></form></div><div class="card p-3 table-responsive"><table class="table"><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Created</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role_name'])?></td><td><?=e($r['status'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></div><?php page_bottom(); ?>